from __future__ import absolute_import

from selenium.webdriver.common.by import By
from taf.selenium.sbts_fsm3.pages import v24r1
from taf.selenium.sbts_fsm3.pages.navigatable_page import NavigatablePage
from taf.selenium.sbts_fsm3.pages.panels.view import ViewPanel


class Procedures(v24r1.Procedures):
    def __init__(self, driver):
        super(Procedures, self).__init__(driver)
        self._change_bts_rnd_parameters = ChangeBtsRndParameterPage(driver)

    @property
    def change_bts_rnd_parameters(self):
        return self._change_bts_rnd_parameters


class ChangeBtsRndParameterPage(NavigatablePage):
    _MENU_ROUTE_LIST = ['Procedures', 'Change BTS R&D Parameters']

    def __init__(self, driver):
        super(ChangeBtsRndParameterPage, self).__init__(driver)
        self._view_panel = ChangeBtsRndParameterPageViewPanel(driver)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST

    def change_bts_rnd_parameters(self, swsystem_component_idx, rnd_setting_type, rnd_in_json_format, timeout=60):
        return self._view_panel.change_bts_rnd_parameters(swsystem_component_idx,
                                                          rnd_setting_type,
                                                          rnd_in_json_format,
                                                          timeout)


class ChangeBtsRndParameterPageViewPanel(ViewPanel):
    _SWSYSTEM_COMPONENT_INDEX = ('//div[*[contains(text(), "Index of SwSystem component")]]'
                                 '/following-sibling::div//input')
    _RND_SETTING_TYPE_BUTTON = '//div[*[contains(text(), "R&D setting type")]]/following-sibling::div//button'
    _RND_SETTING_TYPE_ITEM = '//div[*[contains(text(), "R&D setting type")]]/following-sibling::div//li'
    _RND_JSON_FORMAT = '//div[*[contains(text(), "R&D parameters in JSON format")]]/following-sibling::div//input'
    _EXECUTE = '//button[contains(text(), "Execute")]'
    _EXECUTE_RESULT = '//execution-bar//ui-button/following-sibling::div'
    # _COMPLETED = 'Change BTS R&D parameters completed'
    _ONGOING = 'Changing BTS R&D parameters'

    def __init__(self, driver):
        super(ChangeBtsRndParameterPageViewPanel, self).__init__(driver)

    def change_bts_rnd_parameters(self, swsystem_component_idx, rnd_setting_type, rnd_in_json_format, timeout=60):
        self.insert_text_to_enable_element((By.XPATH, self._SWSYSTEM_COMPONENT_INDEX), swsystem_component_idx, timeout)
        self.select_element_from_dropdown_list_by_text_and_click(rnd_setting_type,
                                                                 (By.XPATH, self._RND_SETTING_TYPE_BUTTON),
                                                                 (By.XPATH, self._RND_SETTING_TYPE_ITEM))
        self.insert_text_to_enable_element((By.XPATH, self._RND_JSON_FORMAT), rnd_in_json_format, timeout)
        self.click_enabled_element((By.XPATH, self._EXECUTE))
        self.wait_for_text_present_in_element((By.XPATH, self._EXECUTE_RESULT), self._ONGOING, timeout)
        self.wait_for_text_not_present_in_element((By.XPATH, self._EXECUTE_RESULT), self._ONGOING, timeout)
        return self.get_text_by_xpath(self._EXECUTE_RESULT)
